const ED_FIN_BONUS = 1.25, ED_RADIANT_MUL = 2, ED_ITEM_BENCH = 10;
/* v1271 LANGUAGES step 2: the data keeps its English words (roles, item slots, tiers and ranks - the code compares them); these give the
   player's language only where they are shown */
function edRoleTxt(r){ switch(r){ case 'Tank': return ewT('draft.role_tank'); case 'Bruiser': return ewT('draft.role_bruiser'); case 'Assassin': return ewT('draft.role_assassin'); case 'Mage': return ewT('draft.role_mage'); case 'Marksman': return ewT('draft.role_marksman'); case 'Support': return ewT('draft.role_support'); case 'Warrior': return ewT('draft.role_warrior'); } return r||''; }
function edCompTxt(c){ switch(c){ case 'Weapon': return ewT('draft.comp_weapon'); case 'Helm': return ewT('draft.comp_helm'); case 'Boots': return ewT('draft.comp_boots'); case 'Armor': return ewT('draft.comp_armor'); case 'Gloves': return ewT('draft.comp_gloves'); case 'Belt': return ewT('draft.comp_belt'); case 'Ring': return ewT('draft.comp_ring'); case 'Amulet': return ewT('draft.comp_amulet'); case 'Relic': return ewT('draft.comp_relic'); } return c||''; }
function edCompStat(c,k){ const m=String(ED_COMP_TXT[c]||'').match(/\d+/), n=m?Math.round(+m[0]*(k==null?1:k)):0;   /* the number of ED_COMP_TXT x k, as edItemStatLines did */
  switch(c){ case 'Weapon': return ewT('draft.stat_weapon',{n}); case 'Helm': return ewT('draft.stat_helm',{n}); case 'Boots': return ewT('draft.stat_boots',{n}); case 'Armor': return ewT('draft.stat_armor',{n}); case 'Gloves': return ewT('draft.stat_gloves',{n}); case 'Belt': return ewT('draft.stat_belt',{n}); case 'Ring': return ewT('draft.stat_ring',{n}); case 'Amulet': return ewT('draft.stat_amulet',{n}); case 'Relic': return ewT('draft.stat_relic',{n}); } return c||''; }
function edTierTxt(id){ switch(id){ case 'green': return ewT('draft.tier_green'); case 'blue': return ewT('draft.tier_blue'); case 'purple': return ewT('draft.tier_purple'); case 'gold': return ewT('draft.tier_gold'); case 'orange': return ewT('draft.tier_orange'); } return ''; }
function edRankLbl(r){ return (r>=1&&r<=4)?ewT('draft.rank_star',{n:r}):''; }
function edRankKit(r){ switch(r){ case 1: return ewT('draft.kit_1'); case 2: return ewT('draft.kit_2'); case 3: return ewT('draft.kit_3'); case 4: return ewT('draft.kit_4'); } return ''; }
function edSynTxt(k,i){ const hi=i>=1; switch(k){   /* ED_SYN[k].d[i] in the player's language */
    case 'Tank': return hi?ewT('draft.syn_tank_4',{a:40,b:10}):ewT('draft.syn_tank_2',{a:20});
    case 'Bruiser': return hi?ewT('draft.syn_bruiser_4',{a:25,b:25,c:10}):ewT('draft.syn_bruiser_2',{a:10,b:10});
    case 'Mage': return hi?ewT('draft.syn_mage',{a:50}):ewT('draft.syn_mage',{a:20});
    case 'Marksman': return hi?ewT('draft.syn_marksman',{a:45}):ewT('draft.syn_marksman',{a:20});
    case 'Assassin': return hi?ewT('draft.syn_assassin_4',{a:35}):ewT('draft.syn_assassin_2',{a:15});
    case 'Support': return hi?ewT('draft.syn_support',{a:25}):ewT('draft.syn_support',{a:10}); }
  return (ED_SYN[k]&&ED_SYN[k].d[i])||''; }
function edOrd(n){ switch(n){ case 1: return ewT('draft.ord_1'); case 2: return ewT('draft.ord_2'); case 3: return ewT('draft.ord_3'); case 4: return ewT('draft.ord_4'); case 5: return ewT('draft.ord_5'); case 6: return ewT('draft.ord_6'); case 7: return ewT('draft.ord_7'); case 8: return ewT('draft.ord_8'); } return ''; }
